/**
 * Generate public/textbooks/paprivo-demo-textbook.pdf — a one-page CC0 demo
 * book generated by Paprivo, used to exercise the hosted-textbook viewer.
 */
import { writeFileSync, mkdirSync } from "node:fs";

const lines = [
  "Paprivo Demo Textbook",
  "",
  "This one-page book was generated by Paprivo and released under CC0,",
  "the public domain dedication. It exists to demonstrate the",
  "hosted-textbook viewer: page navigation, zoom, fullscreen",
  "and open-in-new-tab.",
  "",
  "Replace it by adding genuinely redistributable textbooks to",
  "public/textbooks/ and referencing them in resources.json with",
  'accessType: "hosted", a license and an originalSource.',
];

const content = lines
  .map((l, i) => `BT /F1 13 Tf 60 ${740 - i * 26} Td (${l}) Tj ET`)
  .join("\n");

const objects = [
  "<< /Type /Catalog /Pages 2 0 R >>",
  "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
  "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>",
  `<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
  "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
];

let body = "%PDF-1.4\n";
const offsets = [];
objects.forEach((obj, i) => {
  offsets.push(body.length);
  body += `${i + 1} 0 obj\n${obj}\nendobj\n`;
});
const xrefStart = body.length;
body += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
for (const off of offsets) body += `${String(off).padStart(10, "0")} 00000 n \n`;
body += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;

mkdirSync(new URL("../public/textbooks/", import.meta.url), { recursive: true });
writeFileSync(
  new URL("../public/textbooks/paprivo-demo-textbook.pdf", import.meta.url),
  Buffer.from(body, "latin1"),
);
console.log("demo PDF written");
